// 1. Validation
int config_valid = 1;
if (!isfinite(sa_config.enter_rad) || !isfinite(sa_config.exit_rad) ||
    sa_config.enter_rad < 0.0 || sa_config.exit_rad < 0.0 ||
    sa_config.enter_rad > ADCS_PI || sa_config.exit_rad > ADCS_PI ||
    sa_config.enter_rad >= sa_config.exit_rad || // Strictly less than per "0 <= enter < exit"
    !isfinite(sa_config.acquire_gain_nm_rad) || sa_config.acquire_gain_nm_rad < 0.0 ||
    !isfinite(sa_config.track_gain_nm_rad) || sa_config.track_gain_nm_rad < 0.0 ||
    !isfinite(sa_config.torque_limit_nm) || sa_config.torque_limit_nm <= 0.0 ||
    !isfinite(sa_config.max_slew_nm_per_cycle) || sa_config.max_slew_nm_per_cycle < 0.0 ||
    !isfinite(sa_config.coast_decay) || sa_config.coast_decay < 0.0 ||
    sa_config.coast_decay > 1.0 ||
    sa_config.acquire_samples < 1 || sa_config.acquire_samples > 20 ||
    sa_config.max_coast_samples < 1 || sa_config.max_coast_samples >= sa_config.max_bad_samples ||
    sa_config.max_bad_samples > 20) {
    config_valid = 0;
}

int input_valid = 1;
if (sa_input.enable != TRUE32 && sa_input.enable != FALSE32) input_valid = 0;
if (sa_input.valid != TRUE32 && sa_input.valid != FALSE32) input_valid = 0;

const adcs_vec3_t *m_vec = sa_input.measured_body;
const adcs_vec3_t *t_vec = sa_input.target_body;

if (m_vec == NULL || t_vec == NULL) input_valid = 0;
else if (!adcs_is_finite_vec3(m_vec) || !adcs_is_finite_vec3(t_vec)) input_valid = 0;
else {
    double mn = adcs_vec3_norm(m_vec);
    double tn = adcs_vec3_norm(t_vec);
    if (mn <= ADCS_EPS_NORM || tn <= ADCS_EPS_NORM) input_valid = 0;
}

int rejected = (!config_valid || !input_valid || sa_input.valid != TRUE32);

// 2. Handle Rejection
if (rejected) {
    sa_state.good_samples = 0;

    if (sa_state.mode == SA_TRACK || sa_state.mode == SA_COAST) {
        // Enters/remains COAST
        sa_state.mode = SA_COAST;
        sa_state.coast_samples++;

        // Publish decayed torque
        sa_output.torque_nm = adcs_vec3_scale(&sa_state.previous_torque_nm, sa_config.coast_decay);
        sa_output.rotation_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
        sa_output.error_rad = 0.0;
        sa_output.slew_mask = 0;
        sa_output.mode = sa_state.mode;
        sa_output.good_samples = sa_state.good_samples;
        sa_output.bad_samples = sa_state.bad_samples;
        sa_output.coast_samples = sa_state.coast_samples;

        if (sa_state.coast_samples > sa_config.max_coast_samples) {
            // More than coast allowance -> treat as external rejection
            sa_state.bad_samples++;
            if (sa_state.bad_samples >= sa_config.max_bad_samples) {
                sa_state.mode = SA_FAULT;
            }
        }
    } else {
        // Outside tracking (SEARCH, ACQUIRE, OFF)
        sa_state.bad_samples++;
        if (sa_state.bad_samples >= sa_config.max_bad_samples) {
            sa_state.mode = SA_FAULT;
        }
        // Keep current mode
        sa_output.mode = sa_state.mode;
        sa_output.torque_nm = sa_state.previous_torque_nm;
        sa_output.rotation_axis = (adcs_vec3_t){0,0,0};
        sa_output.error_rad = 0.0;
        sa_output.slew_mask = 0;
        sa_output.good_samples = sa_state.good_samples;
        sa_output.bad_samples = sa_state.bad_samples;
        sa_output.coast_samples = sa_state.coast_samples;
    }
    return;
}

// 3. Acceptance Logic
sa_state.bad_samples = 0;

// Normalize vectors
adcs_vec3_t v_meas, v_tgt;
adcs_vec3_normalize(m_vec, ADCS_EPS_NORM, &v_meas);
adcs_vec3_normalize(t_vec, ADCS_EPS_NORM, &v_tgt);

double dot = adcs_vec3_dot(&v_meas, &v_tgt);
adcs_vec3_t cross = adcs_vec3_cross(&v_meas, &v_tgt);
double norm_cross = adcs_vec3_norm(&cross);
double angle = atan2(norm_cross, dot);

// Determine Axis
adcs_vec3_t axis;
if (dot <= -1.0 + ADCS_EPS_COLLINEAR) {
    // Antiparallel
    double ax = fabs(v_meas.x);
    double ay = fabs(v_meas.y);
    double az = fabs(v_meas.z);

    adcs_vec3_t basis = {0};
    if (ax <= ay && ax <= az) {
        basis.x = 1.0;
    } else if (ay <= ax && ay <= az) {
        basis.y = 1.0;
    } else {
        basis.z = 1.0;
    }

    axis = adcs_vec3_cross(&v_meas, &basis);
    double n = adcs_vec3_norm(&axis);
    if (n > ADCS_EPS_NORM) {
        axis = adcs_vec3_scale(&axis, 1.0 / n);
    } else {
        axis = (adcs_vec3_t){1,0,0};
    }
} else {
    axis = adcs_vec3_scale(&cross, 1.0 / norm_cross);
}

// Mode Transition
sa_mode_t next_mode = sa_state.mode;

// Clear coast samples if leaving COAST
if (sa_state.mode == SA_COAST) {
    sa_state.coast_samples = 0;
}

// Determine target mode based on angle and current mode
if (sa_state.mode == SA_OFF) {
    next_mode = SA_SEARCH;
} else if (sa_state.mode == SA_SEARCH) {
    if (angle <= sa_config.enter_rad) {
        next_mode = SA_ACQUIRE;
    }
} else if (sa_state.mode == SA_ACQUIRE) {
    if (angle > sa_config.exit_rad) {
        next_mode = SA_SEARCH;
        sa_state.good_samples = 0; // Clears evidence
    } else {
        sa_state.good_samples++;
        if (sa_state.good_samples >= sa_config.acquire_samples) {
            next_mode = SA_TRACK;
        }
    }
} else if (sa_state.mode == SA_TRACK) {
    if (angle >= sa_config.exit_rad) {
        next_mode = SA_SEARCH;
    }
} else if (sa_state.mode == SA_COAST) {
    // Valid sample in COAST
    if (angle < sa_config.exit_rad) {
        next_mode = SA_TRACK;
    } else {
        next_mode = SA_SEARCH;
    }
}

sa_state.mode = next_mode;

// Gain Selection
double gain;
if (next_mode == SA_TRACK) {
    gain = sa_config.track_gain_nm_rad;
} else {
    gain = sa_config.acquire_gain_nm_rad;
}

// Compute Torque
adcs_vec3_t raw_torque = adcs_vec3_scale(&axis, gain * angle);

// Limit Magnitude
double mag = adcs_vec3_norm(&raw_torque);
if (mag > sa_config.torque_limit_nm) {
    raw_torque = adcs_vec3_scale(&raw_torque, sa_config.torque_limit_nm / mag);
}

// Slew Limit
adcs_vec3_t limited_torque = raw_torque;
unint32 slew_mask = 0;
for (int i = 0; i < 3; i++) {
    double prev_val = (i == 0) ? sa_state.previous_torque_nm.x : 
                      (i == 1) ? sa_state.previous_torque_nm.y : sa_state.previous_torque_nm.z;
    double curr_val = (i == 0) ? raw_torque.x : 
                      (i == 1) ? raw_torque.y : raw_torque.z;
    double diff = curr_val - prev_val;

    if (fabs(diff) > sa_config.max_slew_nm_per_cycle) {
        double limit_val = prev_val + copysign(sa_config.max_slew_nm_per_cycle, diff);
        if (i == 0) limited_torque.x = limit_val;
        else if (i == 1) limited_torque.y = limit_val;
        else limited_torque.z = limit_val;
        slew_mask |= (1U << i);
    }
}

// Update State
sa_state.previous_torque_nm = limited_torque;

// Fill Output
sa_output.mode = sa_state.mode;
sa_output.good_samples = sa_state.good_samples;
sa_output.bad_samples = sa_state.bad_samples;
sa_output.coast_samples = sa_state.coast_samples;
sa_output.error_rad = angle;
sa_output.rotation_axis = axis;
sa_output.torque_nm = limited_torque;
sa_output.slew_mask = slew_mask;

