if (sa_config.coast_decay < 0.0 || sa_config.coast_decay > 1.0) config_valid = 0;
if (sa_config.acquire_samples < 1 || sa_config.acquire_samples > 20) config_valid = 0;
if (sa_config.max_coast_samples < 1 || sa_config.max_coast_samples >= sa_config.max_bad_samples || 
    sa_config.max_bad_samples > 20) config_valid = 0;

