if (!sa_input.valid) {
    input_valid = 0;
} else if (sa_input.measured_body == NULL || sa_input.target_body == NULL) {
    input_valid = 0;
} else if (!adcs_is_finite_vec3(sa_input.measured_body) || !adcs_is_finite_vec3(sa_input.target_body)) {
    input_valid = 0;
} else {
    if (adcs_vec3_norm(sa_input.measured_body) <= FLT64_ZERO || 
        adcs_vec3_norm(sa_input.target_body) <= FLT64_ZERO) {
        input_valid = 0;
    }
