unint32 slew_mask = 0;
adcs_vec3_t limited_delta = {
    fmin(fmax(diff.x, -sa_config.max_slew_nm_per_cycle), sa_config.max_slew_nm_per_cycle),
    fmin(fmax(diff.y, -sa_config.max_slew_nm_per_cycle), sa_config.max_slew_nm_per_cycle),
    fmin(fmax(diff.z, -sa_config.max_slew_nm_per_cycle), sa_config.max_slew_nm_per_cycle)
