if (limited_delta.x != diff.x) slew_mask |= 1U;
if (limited_delta.y != diff.y) slew_mask |= 2U;
if (limited_delta.z != diff.z) slew_mask |= 4U;

limited_torque = adcs_vec3_add(&sa_state.previous_torque_nm, &limited_delta);
sa_state.previous_torque_nm = limited_torque;

// Output
sa_output.mode = next_mode;
sa_output.error_rad = angle_rad;
sa_output.rotation_axis = axis;
sa_output.torque_nm = limited_torque;
sa_output.slew_mask = slew_mask;

