    input_valid = 0;
} else {
    if (adcs_vec3_norm(sa_input.measured_body) <= 0.0 || 
        adcs_vec3_norm(sa_input.target_body) <= 0.0) {
        input_valid = 0;
    }
}

// 4. 拒绝处理
if (!config_valid || !input_valid) {
    sa_state.bad_samples++;
    sa_state.good_samples = 0;

    if (sa_state.mode == SA_COAST && sa_state.coast_samples < sa_config.max_coast_samples) {
        sa_state.coast_samples++;
        sa_output.mode = SA_COAST;
        sa_output.error_rad = 0.0;
        sa_output.rotation_axis = (adcs_vec3_t){0,0,0};
        sa_output.torque_nm = adcs_vec3_scale(&sa_state.previous_torque_nm, sa_config.coast_decay);
        sa_output.slew_mask = 0;
    } else {
        // Not absorbed by COAST, or COAST allowance exceeded
        // Keep current mode (unless FAULT)
        // Torque: Not specified. Assume zero or hold. Let's hold previous to be safe, or zero.
        // Given "publishes... multiplied by decay" is specific, others might just stop.
        // I will output zero torque for rejected samples that are not coast-decayed.
        sa_output.mode = sa_state.mode;
        sa_output.error_rad = 0.0;
        sa_output.rotation_axis = (adcs_vec3_t){0,0,0};
        sa_output.torque_nm = (adcs_vec3_t){0,0,0};
        sa_output.slew_mask = 0;
    }

    if (sa_state.bad_samples >= sa_config.max_bad_samples) {
        sa_state.mode = SA_FAULT;
        sa_output.mode = SA_FAULT;
        sa_output.torque_nm = (adcs_vec3_t){0,0,0};
    }
    return;
}

// 5. 正常控制律
adcs_status_t st_m = adcs_vec3_normalize(sa_input.measured_body, ADCS_EPS_NORM, &norm_measured);
adcs_status_t st_t = adcs_vec3_normalize(sa_input.target_body, ADCS_EPS_NORM, &norm_target);

dot_val = adcs_vec3_dot(&norm_measured, &norm_target);
cross_vec = adcs_vec3_cross(&norm_measured, &norm_target);
double cross_norm = adcs_vec3_norm(&cross_vec);

// Axis calculation
if (fabs(dot_val + 1.0) < ADCS_EPS_COLLINEAR) {
    double dx = fabs(norm_measured.x);
    double dy = fabs(norm_measured.y);
    double dz = fabs(norm_measured.z);
    if (dx <= dy && dx <= dz) {
        axis = adcs_vec3_cross(&norm_measured, &(const adcs_vec3_t){1,0,0});
    } else if (dy <= dx && dy <= dz) {
        axis = adcs_vec3_cross(&norm_measured, &(const adcs_vec3_t){0,1,0});
    } else {
        axis = adcs_vec3_cross(&norm_measured, &(const adcs_vec3_t){0,0,1});
    }
    double an = adcs_vec3_norm(&axis);
    if (an > 0.0) axis = adcs_vec3_scale(&axis, 1.0 / an);
} else {
    axis = cross_vec;
    double n = adcs_vec3_norm(&axis);
    if (n > 0.0) axis = adcs_vec3_scale(&axis, 1.0 / n);
}

angle_rad = atan2(cross_norm, dot_val);

// Mode Transition
sa_mode_t next_mode = sa_state.mode;
uint32_t new_good = sa_state.good_samples;
uint32_t new_coast = sa_state.coast_samples;
int in_enter_window = (angle_rad <= sa_config.enter_rad);
int in_track_window = (angle_rad < sa_config.exit_rad);

if (sa_state.mode == SA_OFF) next_mode = SA_SEARCH;

switch (sa_state.mode) {
    case SA_SEARCH:
        if (in_enter_window) {
            next_mode = SA_ACQUIRE;
            new_good = 1;
        } else {
            new_good = 0;
        }
        break;
    case SA_ACQUIRE:
        if (in_enter_window) {
            new_good++;
            if (new_good >= sa_config.acquire_samples) next_mode = SA_TRACK;
        } else {
            next_mode = SA_SEARCH;
            new_good = 0;
        }
        break;
    case SA_TRACK:
        if (angle_rad >= sa_config.exit_rad) {
            next_mode = SA_SEARCH;
            new_good = 0;
        }
        break;
    case SA_COAST:
        if (in_track_window) {
            next_mode = SA_TRACK;
            new_coast = 0;
        } else {
            next_mode = SA_SEARCH;
            new_coast = 0;
        }
        break;
    default:
        break;
}

sa_state.mode = next_mode;
sa_state.good_samples = new_good;
sa_state.coast_samples = new_coast;
sa_state.bad_samples = 0;

// Torque Generation
gain = (next_mode == SA_TRACK) ? sa_config.track_gain_nm_rad : sa_config.acquire_gain_nm_rad;
raw_torque = adcs_vec3_scale(&axis, gain * angle_rad);

// Magnitude Limit
double mag = adcs_vec3_norm(&raw_torque);
if (mag > sa_config.torque_limit_nm) {
    raw_torque = adcs_vec3_scale(&raw_torque, sa_config.torque_limit_nm / mag);
}

// Slew Limit
adcs_vec3_t diff = adcs_vec3_sub(&raw_torque, &sa_state.previous_torque_nm);
uint32_t slew_mask = 0;
adcs_vec3_t limited_delta = {
    fmin(fmax(diff.x, -sa_config.max_slew_nm_per_cycle), sa_config.max_slew_nm_per_cycle),
    fmin(fmax(diff.y, -sa_config.max_slew_nm_per_cycle), sa_config.max_slew_nm_per_cycle),
    fmin(fmax(diff.z, -sa_config.max_slew_nm_per_cycle), sa_config.max_slew_nm_per_cycle)
};

if (limited_delta.x != diff.x) slew_mask |= (uint32_t)1U;
if (limited_delta.y != diff.y) slew_mask |= (uint32_t)2U;
if (limited_delta.z != diff.z) slew_mask |= (uint32_t)4U;

limited_torque = adcs_vec3_add(&sa_state.previous_torque_nm, &limited_delta);
sa_state.previous_torque_nm = limited_torque;

// Output
sa_output.mode = next_mode;
sa_output.error_rad = angle_rad;
sa_output.rotation_axis = axis;
sa_output.torque_nm = limited_torque;
sa_output.slew_mask = slew_mask;
